	sign: function (key, message) {
		var hex = hmac(''sha256'', key, message);

		if ((hex.length % 2) === 1) {
			throw ''Invalid length of a hex string!'';
		}

		var result = new Int8Array(hex.length / 2);
		for (var i = 0, b = 0; i < hex.length; i += 2, b++) {
