			''UnHealthyHostCount:Maximum''
		],
			regex = /loadbalancer\\/(.+)$/;

		var metric_payload = [];
		metrics_list.forEach(function (metric, index) {
			var parts = metric.split('':'', 2);
			metric_payload.push({
				''Id'': ''m'' + index,
				''MetricStat'': {
					''Metric'': {
						''MetricName'': parts[0],
