		}
	});

	if (url === ''{'' + ''$SDWAN.API.URL}'') {
		throw ''Please change {'' + ''$SDWAN.API.URL} macro to the proper value.'';
	}

	if (url.indexOf(''http://'') === -1 && url.indexOf(''https://'') === -1) {
		url = ''https://'' + url;
	}

	if (!url.endsWith(''/'')) {
		url += ''/'';
	}

	if (http_proxy !== ''{'' + ''$SDWAN.HTTP_PROXY}'' && http_proxy !== '''') {
